--
-- Name: all_participants_completed_hot(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.all_participants_completed_hot(course_uuid uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  total_participants integer;
  completed_participants integer;
BEGIN
  SELECT COUNT(*) INTO total_participants
  FROM course_participants
  WHERE course_id = course_uuid;
  
  IF total_participants = 0 THEN
    RETURN false;
  END IF;
  
  SELECT COUNT(*) INTO completed_participants
  FROM course_participants
  WHERE course_id = course_uuid AND has_completed_hot = true;
  
  RETURN (total_participants = completed_participants);
END;
$$;


ALTER FUNCTION public.all_participants_completed_hot(course_uuid uuid) OWNER TO postgres;

--
-- Name: calculate_course_average(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_course_average(course_uuid uuid) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
  course_avg decimal;
  all_completed boolean;
BEGIN
  SELECT all_participants_completed_hot(course_uuid) INTO all_completed;
  
  IF NOT all_completed THEN
    RETURN NULL;
  END IF;
  
  SELECT AVG(hq.average_score) INTO course_avg
  FROM hot_questionnaires hq
  INNER JOIN course_participants cp ON cp.id = hq.participant_id
  WHERE cp.course_id = course_uuid AND hq.is_locked = true;
  
  RETURN COALESCE(course_avg, 0);
END;
$$;


ALTER FUNCTION public.calculate_course_average(course_uuid uuid) OWNER TO postgres;

--
-- Name: calculate_hot_questionnaire_average(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_hot_questionnaire_average(questionnaire_uuid uuid) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
  avg_score decimal;
BEGIN
  SELECT AVG(score) INTO avg_score
  FROM hot_section_scores
  WHERE questionnaire_id = questionnaire_uuid;
  
  RETURN COALESCE(avg_score, 0);
END;
$$;


ALTER FUNCTION public.calculate_hot_questionnaire_average(questionnaire_uuid uuid) OWNER TO postgres;

--
-- Name: calculate_questionnaire_average(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_questionnaire_average(questionnaire_uuid uuid) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
avg_score numeric;
BEGIN
SELECT AVG(percentage_value)
INTO avg_score
FROM questionnaire_responses
WHERE questionnaire_id = questionnaire_uuid
AND response_type = 'percentage'
AND percentage_value IS NOT NULL
AND percentage_value > 0;

RETURN COALESCE(avg_score, 0);
END;
$$;


ALTER FUNCTION public.calculate_questionnaire_average(questionnaire_uuid uuid) OWNER TO postgres;

--
-- Name: complete_cold_questionnaire(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_cold_questionnaire(p_questionnaire_id uuid, p_employee_signature_name text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_is_locked boolean;
BEGIN
  SELECT is_locked INTO v_is_locked
  FROM cold_questionnaires
  WHERE id = p_questionnaire_id;

  IF v_is_locked THEN
    RAISE EXCEPTION 'El cuestionario ya está completado y bloqueado.';
  END IF;

  IF p_employee_signature_name IS NULL OR p_employee_signature_name = '' THEN
    RAISE EXCEPTION 'Se requiere la firma del empleado para completar el cuestionario.';
  END IF;

  UPDATE cold_questionnaires
  SET
    signature_employee_name = p_employee_signature_name,
    signature_date = now(),
    is_completed = true,
    is_locked = true
  WHERE id = p_questionnaire_id;

  RETURN true;
END;
$$;


ALTER FUNCTION public.complete_cold_questionnaire(p_questionnaire_id uuid, p_employee_signature_name text) OWNER TO postgres;

--
-- Name: create_cold_questionnaire_with_template(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_cold_questionnaire_with_template(p_participant_id uuid, p_hot_questionnaire_id uuid, p_evaluator_name text, p_template_name text DEFAULT 'cold_standard'::text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_questionnaire_id uuid;
  v_can_create boolean;
BEGIN
  SELECT has_three_months_passed(p_hot_questionnaire_id) INTO v_can_create;

  IF NOT v_can_create THEN
    RAISE EXCEPTION 'No se puede crear el cuestionario frío. Deben pasar 3 meses desde el cuestionario caliente.';
  END IF;

  VALUES (p_participant_id, p_hot_questionnaire_id, p_evaluator_name)
  RETURNING id INTO v_questionnaire_id;

  SELECT
    v_questionnaire_id,
    section_number,
    question_text
  FROM questionnaire_templates
  WHERE template_name = p_template_name
    AND answer_type = 'text'
    AND is_active = true;

  RETURN v_questionnaire_id;
END;
$$;


ALTER FUNCTION public.create_cold_questionnaire_with_template(p_participant_id uuid, p_hot_questionnaire_id uuid, p_evaluator_name text, p_template_name text) OWNER TO postgres;

