-- Name: create_hot_questionnaire_with_template(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_hot_questionnaire_with_template(p_participant_id uuid, p_template_name text DEFAULT 'hot_standard'::text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_questionnaire_id uuid;
BEGIN
  VALUES (p_participant_id)
  RETURNING id INTO v_questionnaire_id;

  SELECT
    v_questionnaire_id,
    section_number,
    question_text,
    5
  FROM questionnaire_templates
  WHERE template_name = p_template_name
    AND answer_type = 'score'
    AND is_active = true;

  SELECT
    v_questionnaire_id,
    section_number,
    question_text,
    false
  FROM questionnaire_templates
  WHERE template_name = p_template_name
    AND answer_type = 'yesno'
    AND is_active = true;

  RETURN v_questionnaire_id;
END;
$$;


