--
-- Name: create_questionnaires_for_participant(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_questionnaires_for_participant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
hot_questionnaire_id uuid;
BEGIN
-- Crear cuestionario CALIENTE (disponible inmediatamente)
course_participant_id,
course_id,
employee_id,
type,
status,
available_from
) VALUES (
NEW.id,
NEW.course_id,
NEW.employee_id,
'hot',
'pending',
now()
) RETURNING id INTO hot_questionnaire_id;

-- Crear respuestas vacías para el cuestionario CALIENTE
-- Sección 1: Evaluación porcentual

-- Sección 2: Sí/No y texto

-- Crear cuestionario FRÍO (disponible 3 meses después)
course_participant_id,
course_id,
employee_id,
type,
status,
available_from
) VALUES (
NEW.id,
NEW.course_id,
NEW.employee_id,
'cold',
'pending',
now() + INTERVAL '3 months'
);

-- Crear respuestas vacías para el cuestionario FRÍO
-- Solo tiene evaluación de eficacia y métodos
SELECT 
q.id,
'efficacy',
'Eficacia',
'percentage',
'evaluator'
FROM questionnaires q
WHERE q.course_participant_id = NEW.id AND q.type = 'cold';

SELECT 
q.id,
'methods_quality',
'Metodos-Calidad de trabajo',
'percentage',
'evaluator'
FROM questionnaires q
WHERE q.course_participant_id = NEW.id AND q.type = 'cold';

RETURN NEW;
END;
$$;


ALTER FUNCTION public.create_questionnaires_for_participant() OWNER TO postgres;

--
-- Name: get_employee_training_report(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_employee_training_report(p_employee_id uuid) RETURNS TABLE(course_name text, course_date date, course_year integer, enrolled_at timestamp with time zone, hot_average numeric, hot_completed timestamp with time zone, cold_completed boolean, cold_signed timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.name AS course_name,
    c.date AS course_date,
    ty.year AS course_year,
    cp.enrolled_at,
    hq.average_score AS hot_average,
    hq.completed_at AS hot_completed,
    cq.is_completed AS cold_completed,
    cq.signature_date AS cold_signed
  FROM course_participants cp
  INNER JOIN courses c ON c.id = cp.course_id
  INNER JOIN training_years ty ON ty.id = c.year_id
  LEFT JOIN hot_questionnaires hq ON hq.participant_id = cp.id
  LEFT JOIN cold_questionnaires cq ON cq.participant_id = cp.id
  WHERE cp.employee_id = p_employee_id
  ORDER BY c.date DESC;
END;
$$;


ALTER FUNCTION public.get_employee_training_report(p_employee_id uuid) OWNER TO postgres;

--
-- Name: get_hot_questionnaire_full(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_hot_questionnaire_full(p_questionnaire_id uuid) RETURNS TABLE(section_number integer, question_text text, answer_type text, answer_value text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    hss.section_number,
    hss.question_text,
    'score'::text AS answer_type,
    hss.score::text AS answer_value
  FROM hot_section_scores hss
  WHERE hss.questionnaire_id = p_questionnaire_id

  UNION ALL

  SELECT
    hsy.section_number,
    hsy.question_text,
    'yesno'::text AS answer_type,
    CASE WHEN hsy.answer THEN 'Sí' ELSE 'No' END AS answer_value
  FROM hot_section_yesno hsy
  WHERE hsy.questionnaire_id = p_questionnaire_id

  ORDER BY section_number;
END;
$$;


ALTER FUNCTION public.get_hot_questionnaire_full(p_questionnaire_id uuid) OWNER TO postgres;

--
-- Name: has_three_months_passed(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.has_three_months_passed(hot_questionnaire_uuid uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  completion_date timestamptz;
BEGIN
  SELECT completed_at INTO completion_date
  FROM hot_questionnaires
  WHERE id = hot_questionnaire_uuid;
  
  IF completion_date IS NULL THEN
    RETURN false;
  END IF;
  
  RETURN (now() >= completion_date + INTERVAL '3 months');
END;
$$;


ALTER FUNCTION public.has_three_months_passed(hot_questionnaire_uuid uuid) OWNER TO postgres;

--
-- Name: lock_hot_questionnaire(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_hot_questionnaire(p_questionnaire_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_is_complete boolean;
BEGIN
  SELECT validate_hot_questionnaire_complete(p_questionnaire_id) INTO v_is_complete;

  IF NOT v_is_complete THEN
    RAISE EXCEPTION 'El cuestionario no está completo. Debe responder todas las preguntas.';
  END IF;

  UPDATE hot_questionnaires
  SET
    completed_at = now(),
    is_locked = true
  WHERE id = p_questionnaire_id
    AND is_locked = false;

  RETURN true;
END;
$$;


ALTER FUNCTION public.lock_hot_questionnaire(p_questionnaire_id uuid) OWNER TO postgres;

