--
-- Name: vw_course_participants_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_course_participants_summary AS
 SELECT c.id AS course_id,
    c.name AS course_name,
    ty.year AS course_year,
    count(cp.id) AS total_participants,
    sum(
        CASE
            WHEN cp.has_completed_hot THEN 1
            ELSE 0
        END) AS completed_hot,
    sum(
        CASE
            WHEN cp.has_completed_cold THEN 1
            ELSE 0
        END) AS completed_cold,
    public.all_participants_completed_hot(c.id) AS all_hot_completed,
    public.calculate_course_average(c.id) AS course_average
   FROM ((public.courses c
     JOIN public.training_years ty ON ((ty.id = c.year_id)))
     LEFT JOIN public.course_participants cp ON ((cp.course_id = c.id)))
  GROUP BY c.id, c.name, ty.year;


ALTER VIEW public.vw_course_participants_summary OWNER TO postgres;

--
-- Name: vw_employee_questionnaires; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_employee_questionnaires AS
 SELECT e.id AS employee_id,
    e.employee_number,
    e.nombre AS full_name,
    e.area,
    e.puesto,
    e.evaluador,
    c.id AS course_id,
    c.name AS course_name,
    cp.enrolled_at,
    hq.id AS hot_questionnaire_id,
    hq.completed_at AS hot_completed_at,
    hq.average_score AS hot_average,
    hq.is_locked AS hot_locked,
    cq.id AS cold_questionnaire_id,
    cq.is_completed AS cold_completed,
    cq.signature_date AS cold_signature_date
   FROM ((((public.employees e
     JOIN public.course_participants cp ON ((cp.employee_id = e.id)))
     JOIN public.courses c ON ((c.id = cp.course_id)))
     LEFT JOIN public.hot_questionnaires hq ON ((hq.participant_id = cp.id)))
     LEFT JOIN public.cold_questionnaires cq ON ((cq.participant_id = cp.id)));


ALTER VIEW public.vw_employee_questionnaires OWNER TO postgres;

